407	func (m rootModel) loadSkillDetail(skill skilldb.SkillRow) tea.Cmd {
408		return func() tea.Msg {
409			stats, err := m.skillDB.SkillStats(m.ctx, skill.Name, skill.SourceAgent)
410			if err != nil {
411				return skillDetailLoadedMsg{err: fmt.Errorf("load skill stats: %w", err)}
412			}
413	
414			sessions, err := m.skillDB.RecentSessions(m.ctx, skill.Name, skill.SourceAgent, 10)
415			if err != nil {
416				return skillDetailLoadedMsg{err: fmt.Errorf("load recent sessions: %w", err)}
417			}
418	
419			friction, err := m.skillDB.SkillFrictionThemes(m.ctx, skill.Name, skill.SourceAgent)
420			if err != nil {
421				return skillDetailLoadedMsg{err: fmt.Errorf("load friction themes: %w", err)}
422			}
423	
424			missing, err := m.skillDB.SkillMissingInstructions(m.ctx, skill.Name, skill.SourceAgent)
425			if err != nil {
426				return skillDetailLoadedMsg{err: fmt.Errorf("load missing instructions: %w", err)}
427			}
428	
429			agents, err := m.skillDB.AgentBreakdown(m.ctx, skill.Name, skill.SourceAgent)
430			if err != nil {
431				return skillDetailLoadedMsg{err: fmt.Errorf("load agent breakdown: %w", err)}
432			}
433	
434			improvements, err := m.skillDB.ListImprovements(m.ctx, skill.Name, skill.SourceAgent, "")
435			if err != nil {
436				return skillDetailLoadedMsg{err: fmt.Errorf("load improvements: %w", err)}
437			}
438	
439			return skillDetailLoadedMsg{
440				stats:        stats,
441				sessions:     sessions,
442				friction:     friction,
443				missing:      missing,
444				agents:       agents,
445				improvements: improvements,
446			}
447		}
448	}
449	
450	func (m rootModel) generateSuggestions() tea.Cmd {
451		return func() tea.Msg {
452			if m.selectedSkill == nil {
453				return generateDoneMsg{err: errors.New("no skill selected")}
454			}
455	
456			skill := *m.selectedSkill
457	
458			// Read skill file content.
459			skillPath := filepath.Join(m.repoRoot, skill.Path)
460			content, err := os.ReadFile(skillPath) //nolint:gosec // path is constructed from repo root + db path
461			if err != nil {
462				return generateDoneMsg{err: fmt.Errorf("read skill file: %w", err)}
463			}
464	
465			// Load data needed for the request.
466			stats, err := m.skillDB.SkillStats(m.ctx, skill.Name, skill.SourceAgent)
467			if err != nil {
468				return generateDoneMsg{err: fmt.Errorf("load stats: %w", err)}
469			}
470	
471			friction, err := m.skillDB.SkillFrictionThemes(m.ctx, skill.Name, skill.SourceAgent)
472			if err != nil {
473				return generateDoneMsg{err: fmt.Errorf("load friction: %w", err)}
474			}
475	
476			missing, err := m.skillDB.SkillMissingInstructions(m.ctx, skill.Name, skill.SourceAgent)
477			if err != nil {
478				return generateDoneMsg{err: fmt.Errorf("load missing: %w", err)}
479			}
480	
481			agents, err := m.skillDB.AgentBreakdown(m.ctx, skill.Name, skill.SourceAgent)
482			if err != nil {
483				return generateDoneMsg{err: fmt.Errorf("load agents: %w", err)}
484			}
485	
486			// Build the request.
487			frictionRate := 0.0
488			if stats.TotalSessions > 0 {
489				frictionRate = float64(stats.TotalFriction) / float64(stats.TotalSessions) * 100
490			}
491	
492			var frictionThemes []skillimprove.FrictionTheme
493			for _, f := range friction {
494				frictionThemes = append(frictionThemes, skillimprove.FrictionTheme{
495					Text:     f.Text,
496					Category: f.Category,
497					Count:    f.Count,
498				})
499			}
500	
501			var missingInstructions []skillimprove.MissingInstruction
502			for _, mi := range missing {
503				missingInstructions = append(missingInstructions, skillimprove.MissingInstruction{
504					Instruction: mi.Instruction,
505					Count:       mi.Count,
506					Evidence:    mi.Evidence,
507				})
508			}
509	
510			var agentBreakdown []skillimprove.AgentStats
511			for _, a := range agents {
512				agentBreakdown = append(agentBreakdown, skillimprove.AgentStats{
513					Agent:        a.Agent,
514					SessionCount: a.SessionCount,
515					AvgScore:     a.AvgScore,
516				})
517			}
518	
519			req := skillimprove.SkillImprovementRequest{
520				SkillName:           skill.Name,
521				SkillPath:           skill.Path,
522				SkillContent:        string(content),
523				FrictionThemes:      frictionThemes,
524				MissingInstructions: missingInstructions,
525				TotalSessions:       stats.TotalSessions,
526				FrictionRate:        frictionRate,
527				AgentBreakdown:      agentBreakdown,
528			}
529	
530			result, err := m.generator.Generate(m.ctx, req)
531			if err != nil {
532				return generateDoneMsg{err: err}
533			}
534	
535			return generateDoneMsg{suggestions: result.Suggestions}
536		}
537	}
538	
539	func (m rootModel) applyDiff(index int) tea.Cmd {
540		return func() tea.Msg {
541			if index >= len(m.improveTab.suggestions) || m.selectedSkill == nil {
542				return applyDiffResultMsg{index: index, err: errors.New("invalid suggestion index")}
543			}
544	
545			sug := m.improveTab.suggestions[index]
546			skillPath := filepath.Join(m.repoRoot, m.selectedSkill.Path)
547	
548			if err := skillimprove.ApplyDiff(skillPath, sug.Diff); err != nil {
549				return applyDiffResultMsg{index: index, err: fmt.Errorf("apply diff: %w", err)}
550			}
551	
552			// Record the applied improvement in the database.
553			imp := skilldb.SkillImprovement{
554				ID:          fmt.Sprintf("%d-%s", time.Now().UnixNano(), m.selectedSkill.Name),
555				SkillName:   m.selectedSkill.Name,
556				SourceAgent: m.selectedSkill.SourceAgent,
557				Title:       sug.Title,
558				Description: sug.Description,
559				Diff:        sug.Diff,
560				Priority:    sug.Priority,
561				Status:      "applied",
562				CreatedAt:   time.Now().UTC(),
563			}
564			appliedAt := time.Now().UTC()
565			imp.AppliedAt = &appliedAt
566	
567			if err := m.skillDB.InsertImprovement(m.ctx, imp); err != nil {
568				// Non-fatal: diff was applied but recording failed.
569				return applyDiffResultMsg{index: index, err: nil}
570			}
571	
572			return applyDiffResultMsg{index: index, err: nil}
573		}
574	}
575	
576	func (m rootModel) activeTabHints() string {
577		switch m.activeTab {
578		case tabStats:
579			return "esc back \u00b7 r refresh \u00b7 q quit"
580		case tabFriction:
581			return "j/k scroll \u00b7 esc back \u00b7 q quit"
582		case tabImprove:
583			return "g generate \u00b7 a apply \u00b7 d dismiss \u00b7 j/k navigate \u00b7 esc back"
584		default:
585			return "q quit"
586		}
587	}
588	
589	func (m rootModel) activeTabInfo() string {
590		switch m.activeTab {
591		case tabStats:
592			if m.statsTab.stats != nil {
593				return fmt.Sprintf("%d sessions", m.statsTab.stats.TotalSessions)
594			}
595		case tabFriction:
596			total := len(m.frictionTab.friction) + len(m.frictionTab.missing)
597			return fmt.Sprintf("%d items", total)
598		case tabImprove:
599			return fmt.Sprintf("%d suggestions", len(m.improveTab.suggestions))
600		}
601		return ""
602	}
603	
604	func (m rootModel) renderHelp() string {
605		var b strings.Builder
606		b.WriteString(m.styles.render(m.styles.bold, "Keyboard Shortcuts"))
607		b.WriteString("\n\n")
608	
609		b.WriteString(m.styles.render(m.styles.title, "Global"))
610		b.WriteString("\n")
611		b.WriteString("  Tab/Shift+Tab  cycle tabs    1-3  jump to tab\n")
612		b.WriteString("  esc            back          q    quit          ?  toggle help\n")
613		b.WriteString("\n")
614	
615		b.WriteString(m.styles.render(m.styles.title, "Stats"))
616		b.WriteString("\n")
617		b.WriteString("  r  refresh data\n")
618		b.WriteString("\n")
619	
620		b.WriteString(m.styles.render(m.styles.title, "Friction & Gaps"))
621		b.WriteString("\n")
622		b.WriteString("  j/k  scroll items\n")
623		b.WriteString("\n")
624	
625		b.WriteString(m.styles.render(m.styles.title, "Improve"))
626		b.WriteString("\n")
627		b.WriteString("  g  generate suggestions    a  apply diff    d  dismiss\n")
628		b.WriteString("  j/k  navigate suggestions\n")
629	
630		return b.String()
631	}
