package skilltui

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/charmbracelet/bubbles/key"
	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/entireio/cli/cmd/entire/cli/insightsdb"
	"github.com/entireio/cli/cmd/entire/cli/skilldb"
	"github.com/entireio/cli/cmd/entire/cli/skillimprove"
)

const (
	screenPicker    = 0
	screenDashboard = 1

	tabStats    = 0
	tabFriction = 1
	tabImprove  = 2

	maxWidth = 120
)

//nolint:recvcheck // bubbletea pattern: value receivers for interface, pointer for mutation
type rootModel struct {
	ctx       context.Context
	screen    int
	activeTab int

	// Current skill
	selectedSkill *skilldb.SkillRow

	// Data sources
	skillDB    *skilldb.SkillDB
	insightsDB *insightsdb.InsightsDB
	generator  *skillimprove.Generator
	repoRoot   string

	// Sub-models
	picker      pickerModel
	statsTab    statsModel
	frictionTab frictionModel
	improveTab  improveModel

	// UI state
	styles   tuiStyles
	width    int
	height   int
	showHelp bool
	errFlash string
	err      error
}

// Run launches the skill improvement TUI program.
func Run(ctx context.Context, skillDBPath, insightsDBPath, repoRoot string) error {
	sdb, err := skilldb.Open(skillDBPath)
	if err != nil {
		return fmt.Errorf("open skill database: %w", err)
	}
	defer sdb.Close()

	idb, err := insightsdb.Open(insightsDBPath)
	if err != nil {
		return fmt.Errorf("open insights database: %w", err)
	}
	defer idb.Close()

	styles := newStyles()
	m := rootModel{
		ctx:        ctx,
		styles:     styles,
		width:      maxWidth,
		skillDB:    sdb,
		insightsDB: idb,
		generator:  &skillimprove.Generator{},
		repoRoot:   repoRoot,
		picker:     newPickerModel(styles),
		improveTab: newImproveModel(styles),
	}

	p := tea.NewProgram(m, tea.WithAltScreen())
	_, runErr := p.Run()
	if runErr != nil {
		return fmt.Errorf("run TUI: %w", runErr)
	}
	return nil
}

func (m rootModel) Init() tea.Cmd {
	return m.loadData()
}

func (m rootModel) loadData() tea.Cmd {
	return func() tea.Msg {
		// Discover skills on disk.
		discovered, err := skilldb.DiscoverSkills(m.repoRoot)
		if err != nil {
			return dataLoadedMsg{err: fmt.Errorf("discover skills: %w", err)}
		}

		// Convert discovered skills to SkillRow for refresh.
		rows := make([]skilldb.SkillRow, len(discovered))
		now := time.Now().UTC()
		for i, d := range discovered {
			rows[i] = skilldb.SkillRow{
				Name:         d.Name,
				SourceAgent:  d.SourceAgent,
				Path:         d.Path,
				Kind:         d.Kind,
				Scope:        d.Scope,
				DiscoveredAt: now,
				LastSeenAt:   now,
			}
		}

		// Refresh cache from insightsdb.
		if _, err = m.skillDB.RefreshFromInsightsDB(m.ctx, m.insightsDB, rows, m.repoRoot); err != nil {
			return dataLoadedMsg{err: fmt.Errorf("refresh skill cache: %w", err)}
		}

		// Load stats for each discovered skill.
		// Use rows directly (not ListSkills) to preserve Scope from discovery.
		stats := make(map[string]*skilldb.SkillStatsResult, len(rows))
		for _, skill := range rows {
			st, statsErr := m.skillDB.SkillStats(m.ctx, skill.Name, skill.SourceAgent)
			if statsErr != nil {
				return dataLoadedMsg{err: fmt.Errorf("skill stats for %q: %w", skill.Name, statsErr)}
			}
			stats[skill.Name+"|"+skill.SourceAgent] = st
		}

		return dataLoadedMsg{skills: rows, stats: stats}
	}
}

//nolint:ireturn // required by bubbletea Model interface
func (m rootModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		return m.handleResize(msg)
	case tea.KeyMsg:
		return m.handleKeyMsg(msg)
	case spinner.TickMsg:
		return m.handleSpinnerTick(msg)
	default:
		return m.handleDataMsg(msg)
	}
}

//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
func (m rootModel) handleResize(msg tea.WindowSizeMsg) (tea.Model, tea.Cmd) {
	m.width = min(msg.Width, maxWidth)
	m.height = msg.Height
	m.picker.setSize(m.width, m.contentHeight())
	m.statsTab.setSize(m.width, m.contentHeight())
	m.frictionTab.setSize(m.width, m.contentHeight())
	m.improveTab.setSize(m.width, m.contentHeight())
	return m, nil
}

//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
func (m rootModel) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	// Always allow ctrl+c to quit.
	if key.Matches(msg, globalKeyMap.Quit) && msg.String() == "ctrl+c" {
		return m, tea.Quit
	}

	if m.screen == screenPicker {
		return m.handlePickerKeys(msg)
	}
	return m.handleDashboardKeys(msg)
}

//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
func (m rootModel) handlePickerKeys(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if key.Matches(msg, globalKeyMap.Quit) {
		return m, tea.Quit
	}
	var cmd tea.Cmd
	m.picker, cmd = m.picker.update(msg)
	return m, cmd
}

//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
func (m rootModel) handleDashboardKeys(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch {
	case key.Matches(msg, globalKeyMap.Quit):
		return m, tea.Quit
	case key.Matches(msg, globalKeyMap.Help):
		m.showHelp = !m.showHelp
		return m, nil
	case key.Matches(msg, globalKeyMap.TabNext):
		m.activeTab = (m.activeTab + 1) % 3
		return m, nil
	case key.Matches(msg, globalKeyMap.TabPrev):
		m.activeTab = (m.activeTab + 2) % 3
		return m, nil
	case key.Matches(msg, globalKeyMap.Tab1):
		m.activeTab = tabStats
		return m, nil
	case key.Matches(msg, globalKeyMap.Tab2):
		m.activeTab = tabFriction
		return m, nil
	case key.Matches(msg, globalKeyMap.Tab3):
		m.activeTab = tabImprove
		return m, nil
	case key.Matches(msg, dashboardKeyMap.Back):
		return m, func() tea.Msg { return backToPickerMsg{} }
	case key.Matches(msg, dashboardKeyMap.Refresh):
		return m, func() tea.Msg { return refreshMsg{} }
	default:
		return m.delegateToActiveTab(msg)
	}
}

//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
func (m rootModel) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
	if m.improveTab.isGenerating {
		var cmd tea.Cmd
		m.improveTab.spinner, cmd = m.improveTab.spinner.Update(msg)
		return m, cmd
	}
	return m, nil
}

//nolint:ireturn,cyclop // returns tea.Model; message dispatch requires many cases
func (m rootModel) handleDataMsg(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case dataLoadedMsg:
		if msg.err != nil {
			m.err = msg.err
			return m, nil
		}
		m.picker.setData(msg.skills, msg.stats)
		return m, nil

	case skillSelectedMsg:
		m.selectedSkill = &msg.skill
		m.screen = screenDashboard
		m.activeTab = tabStats
		return m, m.loadSkillDetail(msg.skill)

	case skillDetailLoadedMsg:
		if msg.err != nil {
			return m, func() tea.Msg { return errorFlashMsg{text: msg.err.Error()} }
		}
		m.statsTab.setData(msg.stats, msg.sessions, msg.agents)
		m.frictionTab.setData(msg.friction, msg.missing)
		m.improveTab.setData(msg.improvements)
		return m, nil

	case backToPickerMsg:
		m.screen = screenPicker
		m.selectedSkill = nil
		m.activeTab = tabStats
		m.showHelp = false
		return m, nil

	case generateStartedMsg:
		m.improveTab.isGenerating = true
		return m, tea.Batch(m.improveTab.spinner.Tick, m.generateSuggestions())

	case generateDoneMsg:
		m.improveTab.isGenerating = false
		if msg.err != nil {
			return m, func() tea.Msg { return errorFlashMsg{text: fmt.Sprintf("generate failed: %v", msg.err)} }
		}
		m.improveTab.suggestions = msg.suggestions
		m.improveTab.selected = 0
		return m, nil

	case applyDiffMsg:
		return m, m.applyDiff(msg.index)

	case applyDiffResultMsg:
		return m.handleApplyResult(msg)

	case dismissSuggestionMsg:
		m.removeSuggestion(msg.index)
		return m, nil

	case refreshMsg:
		return m, m.loadData()

	case errorFlashMsg:
		m.errFlash = msg.text
		return m, tea.Tick(2*time.Second, func(time.Time) tea.Msg { return clearErrorMsg{} })

	case clearErrorMsg:
		m.errFlash = ""
		return m, nil

	default:
		return m.delegateToActiveTab(msg)
	}
}

//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
func (m rootModel) handleApplyResult(msg applyDiffResultMsg) (tea.Model, tea.Cmd) {
	if msg.err != nil {
		return m, func() tea.Msg { return errorFlashMsg{text: fmt.Sprintf("apply failed: %v", msg.err)} }
	}
	m.removeSuggestion(msg.index)
	return m, func() tea.Msg { return errorFlashMsg{text: "Diff applied successfully"} }
}

func (m *rootModel) removeSuggestion(index int) {
	if index < len(m.improveTab.suggestions) {
		m.improveTab.suggestions = append(
			m.improveTab.suggestions[:index],
			m.improveTab.suggestions[index+1:]...,
		)
		if m.improveTab.selected >= len(m.improveTab.suggestions) && m.improveTab.selected > 0 {
			m.improveTab.selected--
		}
	}
}

//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
func (m rootModel) delegateToActiveTab(msg tea.Msg) (tea.Model, tea.Cmd) {
	if m.screen != screenDashboard {
		return m, nil
	}
	var cmd tea.Cmd
	switch m.activeTab {
	case tabStats:
		m.statsTab, cmd = m.statsTab.update(msg)
	case tabFriction:
		m.frictionTab, cmd = m.frictionTab.update(msg)
	case tabImprove:
		m.improveTab, cmd = m.improveTab.update(msg)
	}
	return m, cmd
}

func (m rootModel) View() string {
	if m.err != nil {
		return fmt.Sprintf("Error: %v\n\nCheck database paths and try again.", m.err)
	}

	if m.screen == screenPicker && len(m.picker.skills) == 0 && m.picker.stats == nil {
		return "Loading..."
	}

	var b strings.Builder

	if m.screen == screenPicker {
		b.WriteString(m.picker.view())
		b.WriteString("\n")
		hints := "j/k navigate \u00b7 f filter \u00b7 enter select \u00b7 q quit"
		info := fmt.Sprintf("%d skills", len(m.picker.skills))
		b.WriteString(renderStatusBar(m.styles, hints, info, m.width))
		return b.String()
	}

	// Dashboard screen
	skillName := ""
	if m.selectedSkill != nil {
		skillName = m.selectedSkill.Name
	}

	b.WriteString(renderTabBar(m.styles, m.activeTab, m.width, skillName))
	b.WriteString("\n")

	if m.showHelp {
		b.WriteString(m.renderHelp())
	} else {
		switch m.activeTab {
		case tabStats:
			b.WriteString(m.statsTab.view())
		case tabFriction:
			b.WriteString(m.frictionTab.view())
		case tabImprove:
			b.WriteString(m.improveTab.view())
		}
	}

	// Status bar
	b.WriteString("\n")
	if m.errFlash != "" {
		b.WriteString(m.styles.render(m.styles.errorFlash, m.errFlash))
	} else {
		hints := m.activeTabHints()
		info := m.activeTabInfo()
		b.WriteString(renderStatusBar(m.styles, hints, info, m.width))
	}

	return b.String()
}

func (m rootModel) contentHeight() int {
	// Total height minus tab bar (2) and status bar (1) and newlines (2).
	h := m.height - 5
	if h < 5 {
		h = 5
	}
	return h
}

func (m rootModel) loadSkillDetail(skill skilldb.SkillRow) tea.Cmd {
	return func() tea.Msg {
		stats, err := m.skillDB.SkillStats(m.ctx, skill.Name, skill.SourceAgent)
		if err != nil {
			return skillDetailLoadedMsg{err: fmt.Errorf("load skill stats: %w", err)}
		}

		sessions, err := m.skillDB.RecentSessions(m.ctx, skill.Name, skill.SourceAgent, 10)
		if err != nil {
			return skillDetailLoadedMsg{err: fmt.Errorf("load recent sessions: %w", err)}
		}

		friction, err := m.skillDB.SkillFrictionThemes(m.ctx, skill.Name, skill.SourceAgent)
		if err != nil {
			return skillDetailLoadedMsg{err: fmt.Errorf("load friction themes: %w", err)}
		}

		missing, err := m.skillDB.SkillMissingInstructions(m.ctx, skill.Name, skill.SourceAgent)
		if err != nil {
			return skillDetailLoadedMsg{err: fmt.Errorf("load missing instructions: %w", err)}
		}

		agents, err := m.skillDB.AgentBreakdown(m.ctx, skill.Name, skill.SourceAgent)
		if err != nil {
			return skillDetailLoadedMsg{err: fmt.Errorf("load agent breakdown: %w", err)}
		}

		improvements, err := m.skillDB.ListImprovements(m.ctx, skill.Name, skill.SourceAgent, "")
		if err != nil {
			return skillDetailLoadedMsg{err: fmt.Errorf("load improvements: %w", err)}
		}

		return skillDetailLoadedMsg{
			stats:        stats,
			sessions:     sessions,
			friction:     friction,
			missing:      missing,
			agents:       agents,
			improvements: improvements,
		}
	}
}

func (m rootModel) generateSuggestions() tea.Cmd {
	return func() tea.Msg {
		if m.selectedSkill == nil {
			return generateDoneMsg{err: errors.New("no skill selected")}
		}

		skill := *m.selectedSkill

		// Read skill file content.
		skillPath := filepath.Join(m.repoRoot, skill.Path)
		content, err := os.ReadFile(skillPath) //nolint:gosec // path is constructed from repo root + db path
		if err != nil {
			return generateDoneMsg{err: fmt.Errorf("read skill file: %w", err)}
		}

		// Load data needed for the request.
		stats, err := m.skillDB.SkillStats(m.ctx, skill.Name, skill.SourceAgent)
		if err != nil {
			return generateDoneMsg{err: fmt.Errorf("load stats: %w", err)}
		}

		friction, err := m.skillDB.SkillFrictionThemes(m.ctx, skill.Name, skill.SourceAgent)
		if err != nil {
			return generateDoneMsg{err: fmt.Errorf("load friction: %w", err)}
		}

		missing, err := m.skillDB.SkillMissingInstructions(m.ctx, skill.Name, skill.SourceAgent)
		if err != nil {
			return generateDoneMsg{err: fmt.Errorf("load missing: %w", err)}
		}

		agents, err := m.skillDB.AgentBreakdown(m.ctx, skill.Name, skill.SourceAgent)
		if err != nil {
			return generateDoneMsg{err: fmt.Errorf("load agents: %w", err)}
		}

		// Build the request.
		frictionRate := 0.0
		if stats.TotalSessions > 0 {
			frictionRate = float64(stats.TotalFriction) / float64(stats.TotalSessions) * 100
		}

		var frictionThemes []skillimprove.FrictionTheme
		for _, f := range friction {
			frictionThemes = append(frictionThemes, skillimprove.FrictionTheme{
				Text:     f.Text,
				Category: f.Category,
				Count:    f.Count,
			})
		}

		var missingInstructions []skillimprove.MissingInstruction
		for _, mi := range missing {
			missingInstructions = append(missingInstructions, skillimprove.MissingInstruction{
				Instruction: mi.Instruction,
				Count:       mi.Count,
				Evidence:    mi.Evidence,
			})
		}

		var agentBreakdown []skillimprove.AgentStats
		for _, a := range agents {
			agentBreakdown = append(agentBreakdown, skillimprove.AgentStats{
				Agent:        a.Agent,
				SessionCount: a.SessionCount,
				AvgScore:     a.AvgScore,
			})
		}

		req := skillimprove.SkillImprovementRequest{
			SkillName:           skill.Name,
			SkillPath:           skill.Path,
			SkillContent:        string(content),
			FrictionThemes:      frictionThemes,
			MissingInstructions: missingInstructions,
			TotalSessions:       stats.TotalSessions,
			FrictionRate:        frictionRate,
			AgentBreakdown:      agentBreakdown,
		}

		result, err := m.generator.Generate(m.ctx, req)
		if err != nil {
			return generateDoneMsg{err: err}
		}

		return generateDoneMsg{suggestions: result.Suggestions}
	}
}

func (m rootModel) applyDiff(index int) tea.Cmd {
	return func() tea.Msg {
		if index >= len(m.improveTab.suggestions) || m.selectedSkill == nil {
			return applyDiffResultMsg{index: index, err: errors.New("invalid suggestion index")}
		}

		sug := m.improveTab.suggestions[index]
		skillPath := filepath.Join(m.repoRoot, m.selectedSkill.Path)

		if err := skillimprove.ApplyDiff(skillPath, sug.Diff); err != nil {
			return applyDiffResultMsg{index: index, err: fmt.Errorf("apply diff: %w", err)}
		}

		// Record the applied improvement in the database.
		imp := skilldb.SkillImprovement{
			ID:          fmt.Sprintf("%d-%s", time.Now().UnixNano(), m.selectedSkill.Name),
			SkillName:   m.selectedSkill.Name,
			SourceAgent: m.selectedSkill.SourceAgent,
			Title:       sug.Title,
			Description: sug.Description,
			Diff:        sug.Diff,
			Priority:    sug.Priority,
			Status:      "applied",
			CreatedAt:   time.Now().UTC(),
		}
		appliedAt := time.Now().UTC()
		imp.AppliedAt = &appliedAt

		if err := m.skillDB.InsertImprovement(m.ctx, imp); err != nil {
			// Non-fatal: diff was applied but recording failed.
			return applyDiffResultMsg{index: index, err: nil}
		}

		return applyDiffResultMsg{index: index, err: nil}
	}
}

func (m rootModel) activeTabHints() string {
	switch m.activeTab {
	case tabStats:
		return "esc back \u00b7 r refresh \u00b7 q quit"
	case tabFriction:
		return "j/k scroll \u00b7 esc back \u00b7 q quit"
	case tabImprove:
		return "g generate \u00b7 a apply \u00b7 d dismiss \u00b7 j/k navigate \u00b7 esc back"
	default:
		return "q quit"
	}
}

func (m rootModel) activeTabInfo() string {
	switch m.activeTab {
	case tabStats:
		if m.statsTab.stats != nil {
			return fmt.Sprintf("%d sessions", m.statsTab.stats.TotalSessions)
		}
	case tabFriction:
		total := len(m.frictionTab.friction) + len(m.frictionTab.missing)
		return fmt.Sprintf("%d items", total)
	case tabImprove:
		return fmt.Sprintf("%d suggestions", len(m.improveTab.suggestions))
	}
	return ""
}

func (m rootModel) renderHelp() string {
	var b strings.Builder
	b.WriteString(m.styles.render(m.styles.bold, "Keyboard Shortcuts"))
	b.WriteString("\n\n")

	b.WriteString(m.styles.render(m.styles.title, "Global"))
	b.WriteString("\n")
	b.WriteString("  Tab/Shift+Tab  cycle tabs    1-3  jump to tab\n")
	b.WriteString("  esc            back          q    quit          ?  toggle help\n")
	b.WriteString("\n")

	b.WriteString(m.styles.render(m.styles.title, "Stats"))
	b.WriteString("\n")
	b.WriteString("  r  refresh data\n")
	b.WriteString("\n")

	b.WriteString(m.styles.render(m.styles.title, "Friction & Gaps"))
	b.WriteString("\n")
	b.WriteString("  j/k  scroll items\n")
	b.WriteString("\n")

	b.WriteString(m.styles.render(m.styles.title, "Improve"))
	b.WriteString("\n")
	b.WriteString("  g  generate suggestions    a  apply diff    d  dismiss\n")
	b.WriteString("  j/k  navigate suggestions\n")

	return b.String()
}

package memorylooptui

import (
	"fmt"
	"strconv"
	"strings"

	"github.com/charmbracelet/bubbles/key"
	"github.com/charmbracelet/bubbles/table"
	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/entireio/cli/cmd/entire/cli/memoryloop"
)

type statusFilter int

const (
	filterAll statusFilter = iota
	filterActive
	filterCandidate
	filterSuppressed
	filterArchived
)

var filterLabels = [5]string{"ALL", "ACTIVE", "CANDIDATE", "SUPPRESSED", "ARCHIVED"}

//nolint:recvcheck // bubbletea pattern: pointer receivers for mutation, value for update/view
type memoriesModel struct {
	state      *memoryloop.State
	styles     tuiStyles
	width      int
	height     int
	table      table.Model
	filter     statusFilter
	showDetail bool
	searchMode bool
	searchText string
	records    []memoryloop.MemoryRecord // filtered subset
	addMode    bool
	addFields  [4]textinput.Model // kind, title, body, scope
	addFocus   int
}

func newMemoriesModel(s tuiStyles) memoriesModel {
	columns := []table.Column{
		{Title: " ", Width: 2},
		{Title: "Title", Width: 30},
		{Title: "Kind", Width: 14},
		{Title: "Scope", Width: 5},
		{Title: "Str", Width: 5},
		{Title: "Outcome", Width: 11},
		{Title: "Inj", Width: 4},
	}
	t := table.New(
		table.WithColumns(columns),
		table.WithFocused(true),
	)
	st := table.DefaultStyles()
	st.Header = st.Header.
		BorderStyle(lipgloss.NormalBorder()).
		BorderBottom(true).
		Bold(false).
		Faint(true)
	st.Selected = st.Selected.
		Foreground(lipgloss.Color("214")).
		Bold(false)
	t.SetStyles(st)

	return memoriesModel{
		styles:     s,
		table:      t,
		showDetail: true,
	}
}

// capturesInput returns true when the memories tab is handling keyboard input
// internally (add form or search mode), so the root model should skip global keys.
func (m memoriesModel) capturesInput() bool {
	return m.addMode || m.searchMode
}

func newAddFields() [4]textinput.Model {
	kind := textinput.New()
	kind.Placeholder = "repo_rule | workflow_rule | agent_instruction | skill_patch | anti_pattern"
	kind.Prompt = "Kind: "
	kind.Width = 60

	title := textinput.New()
	title.Placeholder = "memory title"
	title.Prompt = "Title: "
	title.Width = 60

	body := textinput.New()
	body.Placeholder = "memory body"
	body.Prompt = "Body: "
	body.Width = 60

	scope := textinput.New()
	scope.Placeholder = "me | repo"
	scope.Prompt = "Scope: "
	scope.Width = 20
	scope.SetValue("me")

	return [4]textinput.Model{kind, title, body, scope}
}

func (m *memoriesModel) setState(state *memoryloop.State) {
	m.state = state
	m.rebuildTable()
}

func (m *memoriesModel) setSize(w, h int) {
	m.width = w
	m.height = h
	// Reserve 3 lines for filter bar + detail pane header area
	tableH := h - 3
	if m.showDetail {
		tableH = h / 2
	}
	if tableH < 3 {
		tableH = 3
	}
	m.table.SetWidth(w)
	m.table.SetHeight(tableH)
}

func (m *memoriesModel) rebuildTable() {
	if m.state == nil || m.state.Store == nil {
		m.records = nil
		m.table.SetRows(nil)
		return
	}

	var filtered []memoryloop.MemoryRecord
	for _, r := range m.state.Store.Records {
		if !m.matchesFilter(r) {
			continue
		}
		if m.searchMode && m.searchText != "" {
			if !strings.Contains(strings.ToLower(r.Title), strings.ToLower(m.searchText)) {
				continue
			}
		}
		filtered = append(filtered, r)
	}
	m.records = filtered

	rows := make([]table.Row, len(filtered))
	for i, r := range filtered {
		rows[i] = table.Row{
			statusDotPlain(r.Status),
			truncate(r.Title, 30),
			string(r.Kind),
			string(r.ScopeKind),
			renderStrengthBar(r.Strength),
			string(r.Outcome),
			strconv.Itoa(r.InjectCount),
		}
	}
	m.table.SetRows(rows)
}

func (m memoriesModel) matchesFilter(r memoryloop.MemoryRecord) bool {
	switch m.filter {
	case filterAll:
		return true
	case filterActive:
		return r.Status == memoryloop.StatusActive
	case filterCandidate:
		return r.Status == memoryloop.StatusCandidate
	case filterSuppressed:
		return r.Status == memoryloop.StatusSuppressed
	case filterArchived:
		return r.Status == memoryloop.StatusArchived
	default:
		return true
	}
}

func (m memoriesModel) selectedRecord() *memoryloop.MemoryRecord {
	cursor := m.table.Cursor()
	if cursor < 0 || cursor >= len(m.records) {
		return nil
	}
	return &m.records[cursor]
}

func (m memoriesModel) update(msg tea.Msg) (memoriesModel, tea.Cmd) {
	if keyMsg, ok := msg.(tea.KeyMsg); ok {
		if m.addMode {
			return m.updateAddForm(keyMsg)
		}

		if m.searchMode {
			return m.updateSearch(keyMsg)
		}

		switch {
		case key.Matches(keyMsg, memoriesKeyMap.New):
			m.addMode = true
			m.addFields = newAddFields()
			m.addFocus = 0
			m.addFields[0].Focus()
			return m, textinput.Blink

		case key.Matches(keyMsg, memoriesKeyMap.Filter):
			m.filter = (m.filter + 1) % 5
			m.rebuildTable()
			return m, nil

		case key.Matches(keyMsg, memoriesKeyMap.Search):
			m.searchMode = true
			m.searchText = ""
			return m, nil

		case key.Matches(keyMsg, memoriesKeyMap.Enter):
			m.showDetail = !m.showDetail
			m.setSize(m.width, m.height)
			return m, nil

		case key.Matches(keyMsg, memoriesKeyMap.Activate):
			if r := m.selectedRecord(); r != nil {
				return m, func() tea.Msg {
					return lifecycleActionMsg{id: r.ID, action: memoryloop.LifecycleActionActivate}
				}
			}

		case key.Matches(keyMsg, memoriesKeyMap.Promote):
			if r := m.selectedRecord(); r != nil {
				return m, func() tea.Msg {
					return lifecycleActionMsg{id: r.ID, action: memoryloop.LifecycleActionPromote}
				}
			}

		case key.Matches(keyMsg, memoriesKeyMap.Suppress):
			if r := m.selectedRecord(); r != nil {
				return m, func() tea.Msg {
					return lifecycleActionMsg{id: r.ID, action: memoryloop.LifecycleActionSuppress}
				}
			}

		case key.Matches(keyMsg, memoriesKeyMap.Unsuppress):
			if r := m.selectedRecord(); r != nil {
				return m, func() tea.Msg {
					return lifecycleActionMsg{id: r.ID, action: memoryloop.LifecycleActionUnsuppress}
				}
			}

		case key.Matches(keyMsg, memoriesKeyMap.Archive):
			if r := m.selectedRecord(); r != nil {
				return m, func() tea.Msg {
					return lifecycleActionMsg{id: r.ID, action: memoryloop.LifecycleActionArchive}
				}
			}

		case key.Matches(keyMsg, memoriesKeyMap.Prune):
			return m, func() tea.Msg { return pruneMsg{} }
		}
	}

	// Delegate to table for navigation
	var cmd tea.Cmd
	m.table, cmd = m.table.Update(msg)
	return m, cmd
}

func (m memoriesModel) updateSearch(msg tea.KeyMsg) (memoriesModel, tea.Cmd) {
	switch {
	case key.Matches(msg, memoriesKeyMap.Escape):
		m.searchMode = false
		m.searchText = ""
		m.rebuildTable()
		return m, nil
	case msg.Type == tea.KeyEnter:
		m.searchMode = false
		return m, nil
	case msg.Type == tea.KeyBackspace:
		if len(m.searchText) > 0 {
			runes := []rune(m.searchText)
			m.searchText = string(runes[:len(runes)-1])
			m.rebuildTable()
		}
		return m, nil
	default:
		if len(msg.Runes) > 0 {
			m.searchText += string(msg.Runes)
			m.rebuildTable()
		}
		return m, nil
	}
}

func (m memoriesModel) updateAddForm(msg tea.KeyMsg) (memoriesModel, tea.Cmd) {
	switch {
	case key.Matches(msg, memoriesKeyMap.Escape):
		m.addMode = false
		return m, nil

	case msg.String() == "tab":
		// Blur current, advance focus, focus next
		m.addFields[m.addFocus].Blur()
		m.addFocus = (m.addFocus + 1) % len(m.addFields)
		m.addFields[m.addFocus].Focus()
		return m, textinput.Blink

	case msg.String() == "shift+tab":
		m.addFields[m.addFocus].Blur()
		m.addFocus = (m.addFocus + len(m.addFields) - 1) % len(m.addFields)
		m.addFields[m.addFocus].Focus()
		return m, textinput.Blink

	case msg.String() == "enter":
		if m.addFocus < len(m.addFields)-1 {
			// Not on last field -- advance to next
			m.addFields[m.addFocus].Blur()
			m.addFocus++
			m.addFields[m.addFocus].Focus()
			return m, textinput.Blink
		}
		// On last field -- submit
		input := memoryloop.ManualRecordInput{
			Kind:       memoryloop.Kind(m.addFields[0].Value()),
			Title:      m.addFields[1].Value(),
			Body:       m.addFields[2].Value(),
			ScopeKind:  memoryloop.ScopeKind(m.addFields[3].Value()),
			ScopeValue: "",
		}
		m.addMode = false
		return m, func() tea.Msg { return addMemoryMsg{input: input} }
	}

	// Delegate to the focused text input for character input
	var cmd tea.Cmd
	m.addFields[m.addFocus], cmd = m.addFields[m.addFocus].Update(msg)
	return m, cmd
}

func (m memoriesModel) view() string {
	if m.addMode {
		return m.renderAddForm()
	}

	if m.state == nil || m.state.Store == nil {
		return "\n  No memory store found. Switch to History tab and press R to refresh.\n"
	}
	if len(m.state.Store.Records) == 0 {
		return "\n  No memories yet. Press n to add one, or switch to History tab and press R to refresh.\n"
	}
	if len(m.records) == 0 {
		return fmt.Sprintf("\n  No %s memories. Press f to change filter.\n", filterLabels[m.filter])
	}

	var b strings.Builder

	// Blank line for spacing between tab bar and filter bar
	b.WriteString("\n")

	// Filter bar
	b.WriteString(m.renderFilterBar())
	b.WriteString("\n\n")

	// Search bar (if active)
	if m.searchMode {
		fmt.Fprintf(&b, "  / %s\u2588\n", m.searchText)
	}

	// Table
	b.WriteString(m.table.View())

	// Detail pane with spacing above
	if m.showDetail {
		b.WriteString("\n\n")
		b.WriteString(m.renderDetail())
	}

	return b.String()
}

func (m memoriesModel) renderAddForm() string {
	var b strings.Builder
	b.WriteString("\n  ")
	b.WriteString(m.styles.render(m.styles.title, "NEW MEMORY"))
	b.WriteString("\n\n")
	for i := range m.addFields {
		b.WriteString("  ")
		b.WriteString(m.addFields[i].View())
		b.WriteString("\n")
	}
	b.WriteString("\n  ")
	b.WriteString(m.styles.render(m.styles.dim, "Tab next field | Enter submit | Esc cancel"))
	b.WriteString("\n")
	return b.String()
}

func (m memoriesModel) renderFilterBar() string {
	counts := m.statusCounts()
	var parts []string
	for i, label := range filterLabels {
		text := fmt.Sprintf("%s (%d)", label, counts[i])
		if m.styles.colorEnabled {
			if statusFilter(i) == m.filter {
				parts = append(parts, m.styles.filterChipActive.Render(text))
			} else {
				parts = append(parts, m.styles.filterChipInactive.Render(text))
			}
		} else {
			if statusFilter(i) == m.filter {
				parts = append(parts, "["+text+"]")
			} else {
				parts = append(parts, " "+text+" ")
			}
		}
	}
	return "  " + strings.Join(parts, " ")
}

func (m memoriesModel) statusCounts() [5]int {
	var counts [5]int
	if m.state == nil || m.state.Store == nil {
		return counts
	}
	for _, r := range m.state.Store.Records {
		counts[0]++ // all
		switch r.Status {
		case memoryloop.StatusActive:
			counts[1]++
		case memoryloop.StatusCandidate:
			counts[2]++
		case memoryloop.StatusSuppressed:
			counts[3]++
		case memoryloop.StatusArchived:
			counts[4]++
		}
	}
	return counts
}

func (m memoriesModel) renderDetail() string {
	r := m.selectedRecord()
	if r == nil {
		return ""
	}

	var out strings.Builder
	out.WriteString("  ")
	out.WriteString(m.styles.render(m.styles.sectionHeader, "DETAILS"))
	out.WriteString("\n")

	var b strings.Builder
	// Title line
	b.WriteString(m.styles.render(m.styles.title, r.Title))
	b.WriteString("\n\n")

	// Metadata line (kind, status, scope, origin)
	b.WriteString(kindStyle(m.styles, r.Kind)(string(r.Kind)))
	b.WriteString("  ")
	b.WriteString(statusDot(m.styles, r.Status))
	b.WriteString(" ")
	b.WriteString(string(r.Status))
	b.WriteString("  ")
	b.WriteString(m.styles.render(m.styles.dim, string(r.ScopeKind)))
	b.WriteString("  ")
	b.WriteString(m.styles.render(m.styles.dim, string(r.Origin)))

	// Body
	if r.Body != "" {
		b.WriteString("\n\n")
		b.WriteString(r.Body)
	}

	// Why
	if r.Why != "" {
		b.WriteString("\n\n")
		b.WriteString(m.styles.render(m.styles.dim, "WHY"))
		b.WriteString("\n")
		b.WriteString(r.Why)
	}

	// Stats
	b.WriteString("\n\n")
	stats := fmt.Sprintf("strength: %d/5 · injected: %dx · matched: %dx · last injected: %s · created: %s",
		r.Strength, r.InjectCount, r.MatchCount, timeAgo(r.LastInjectedAt), timeAgo(r.CreatedAt))
	b.WriteString(m.styles.render(m.styles.dim, stats))

	// Wrap in bordered card
	cardStyle := lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color("245")).
		Padding(1, 2).
		Width(m.width - 2)
	out.WriteString(cardStyle.Render(b.String()))
	return out.String()
}

func statusDotPlain(status memoryloop.Status) string {
	switch status {
	case memoryloop.StatusActive:
		return "\u25cf"
	case memoryloop.StatusCandidate:
		return "\u25cb"
	case memoryloop.StatusSuppressed:
		return "\u2715"
	case memoryloop.StatusArchived:
		return "\u25cc"
	default:
		return " "
	}
}

func truncate(s string, maxLen int) string {
	runes := []rune(s)
	if len(runes) <= maxLen {
		return s
	}
	return string(runes[:maxLen-1]) + "\u2026"
}

package memorylooptui

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/charmbracelet/bubbles/key"
	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/entireio/cli/cmd/entire/cli/memoryloop"
)

const (
	tabMemories  = 0
	tabInjection = 1
	tabHistory   = 2
	tabSettings  = 3
	maxWidth     = 120
)

//nolint:recvcheck // bubbletea pattern: value receivers for interface, pointer for pushState mutation
type rootModel struct {
	ctx          context.Context
	activeTab    int
	state        *memoryloop.State
	styles       tuiStyles
	width        int
	height       int
	showHelp     bool
	isRefreshing bool
	spinner      spinner.Model
	err          error
	errFlash     string

	memoriesTab  memoriesModel
	injectionTab injectionModel
	historyTab   historyModel
	settingsTab  settingsModel
}

// Run launches the TUI program.
func Run(ctx context.Context) error {
	s := spinner.New()
	s.Spinner = spinner.Dot

	styles := newStyles()
	m := rootModel{
		ctx:          ctx,
		styles:       styles,
		width:        maxWidth, // will be updated by tea.WindowSizeMsg
		spinner:      s,
		memoriesTab:  newMemoriesModel(styles),
		injectionTab: newInjectionModel(styles),
		historyTab:   newHistoryModel(styles),
	}

	p := tea.NewProgram(m, tea.WithAltScreen())
	_, err := p.Run()
	if err != nil {
		return fmt.Errorf("run TUI: %w", err)
	}
	return nil
}

func (m rootModel) Init() tea.Cmd {
	return func() tea.Msg {
		state, err := memoryloop.LoadState(m.ctx)
		return stateLoadedMsg{state: state, err: err}
	}
}

func (m rootModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmds []tea.Cmd

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = min(msg.Width, maxWidth)
		m.height = msg.Height
		m.memoriesTab.setSize(m.width, m.contentHeight())
		m.injectionTab.setSize(m.width, m.contentHeight())
		m.historyTab.setSize(m.width, m.contentHeight())
		m.settingsTab.setSize(m.width, m.contentHeight())
		return m, nil

	case tea.KeyMsg:
		// Allow ctrl+c to always quit, even when a sub-model captures input.
		if key.Matches(msg, globalKeyMap.Quit) && msg.String() == "ctrl+c" {
			return m, tea.Quit
		}

		// When a sub-model is capturing input (add form, search, text input),
		// skip global key handling so Tab/Esc/number keys reach the sub-model.
		tabCapturesInput := (m.activeTab == tabMemories && m.memoriesTab.capturesInput()) ||
			(m.activeTab == tabInjection && m.injectionTab.inputFocus)

		if !tabCapturesInput {
			// Global keys -- check before delegating to tabs
			switch {
			case key.Matches(msg, globalKeyMap.Quit):
				return m, tea.Quit
			case key.Matches(msg, globalKeyMap.Help):
				m.showHelp = !m.showHelp
				return m, nil
			case key.Matches(msg, globalKeyMap.TabNext):
				m.activeTab = (m.activeTab + 1) % 4
				return m, nil
			case key.Matches(msg, globalKeyMap.TabPrev):
				m.activeTab = (m.activeTab + 3) % 4
				return m, nil
			case key.Matches(msg, globalKeyMap.Tab1):
				m.activeTab = tabMemories
				return m, nil
			case key.Matches(msg, globalKeyMap.Tab2):
				m.activeTab = tabInjection
				return m, nil
			case key.Matches(msg, globalKeyMap.Tab3):
				m.activeTab = tabHistory
				return m, nil
			case key.Matches(msg, globalKeyMap.Tab4):
				m.activeTab = tabSettings
				return m, nil
			}
		}

	case stateLoadedMsg:
		if msg.err != nil {
			m.err = msg.err
			return m, nil
		}
		m.state = msg.state
		m.pushState()
		return m, nil

	case lifecycleActionMsg:
		return m.handleLifecycleAction(msg)

	case addMemoryMsg:
		return m.handleAddMemory(msg)

	case pruneMsg:
		return m.handlePrune()

	case settingsChangedMsg:
		return m.handleSettingsChanged(msg)

	case testPromptMsg:
		if m.state == nil || m.state.Store == nil {
			return m, nil
		}
		matches := memoryloop.SelectRelevant(*m.state.Store, msg.prompt, time.Now())
		return m, func() tea.Msg { return testPromptResultMsg{matches: matches} }

	case refreshStartedMsg:
		if m.isRefreshing {
			return m, nil
		}
		m.isRefreshing = true
		// Full async refresh will be added in a later task.
		return m, func() tea.Msg {
			return errorFlashMsg{text: "Refresh not yet implemented in TUI. Use: entire memory-loop refresh"}
		}

	case errorFlashMsg:
		m.errFlash = msg.text
		return m, tea.Tick(2*time.Second, func(time.Time) tea.Msg { return clearErrorMsg{} })

	case clearErrorMsg:
		m.errFlash = ""
		return m, nil
	}

	// Delegate to active tab
	var cmd tea.Cmd
	switch m.activeTab {
	case tabMemories:
		m.memoriesTab, cmd = m.memoriesTab.update(msg)
	case tabInjection:
		m.injectionTab, cmd = m.injectionTab.update(msg)
	case tabHistory:
		m.historyTab, cmd = m.historyTab.update(msg)
	case tabSettings:
		m.settingsTab, cmd = m.settingsTab.update(msg)
	}
	if cmd != nil {
		cmds = append(cmds, cmd)
	}

	return m, tea.Batch(cmds...)
}

func (m rootModel) View() string {
	if m.err != nil {
		return fmt.Sprintf("Error loading memory store: %v\nCheck .entire/memory-loop.json", m.err)
	}
	if m.state == nil {
		return "Loading..."
	}

	var b strings.Builder

	// Tab bar
	mode := memoryloop.ModeOff
	policy := memoryloop.ActivationPolicyReview
	if m.state.Store != nil {
		mode = m.state.Store.Mode
		policy = m.state.Store.ActivationPolicy
	}
	b.WriteString(renderTabBar(m.styles, m.activeTab, m.width, mode, policy))
	b.WriteString("\n")

	// Content area
	if m.showHelp {
		b.WriteString(m.renderHelp())
	} else {
		switch m.activeTab {
		case tabMemories:
			b.WriteString(m.memoriesTab.view())
		case tabInjection:
			b.WriteString(m.injectionTab.view())
		case tabHistory:
			b.WriteString(m.historyTab.view())
		case tabSettings:
			b.WriteString(m.settingsTab.view())
		}
	}

	// Status bar
	b.WriteString("\n")
	if m.errFlash != "" {
		b.WriteString(m.styles.render(m.styles.errorFlash, m.errFlash))
	} else {
		hints := m.activeTabHints()
		info := m.activeTabInfo()
		b.WriteString(renderStatusBar(m.styles, hints, info, m.width))
	}

	return b.String()
}

func (m rootModel) contentHeight() int {
	// Total height minus tab bar (2) and status bar (1) and newlines (2)
	h := m.height - 5
	if h < 5 {
		h = 5
	}
	return h
}

func (m *rootModel) pushState() {
	m.memoriesTab.setState(m.state)
	m.injectionTab.setState(m.state)
	m.historyTab.setState(m.state)
	m.settingsTab.setState(m.state)
}

func (m rootModel) saveState() error {
	return memoryloop.SaveState(m.ctx, m.state) //nolint:wrapcheck // internal helper, callers wrap
}

func (m rootModel) handleLifecycleAction(msg lifecycleActionMsg) (tea.Model, tea.Cmd) {
	if m.state == nil || m.state.Store == nil || m.isRefreshing {
		return m, nil
	}
	updated, _, err := memoryloop.TransitionRecordLifecycle(m.state.Store.Records, msg.id, msg.action, time.Now())
	if err != nil {
		return m, func() tea.Msg { return errorFlashMsg{text: err.Error()} }
	}
	m.state.Store.Records = updated
	if err := m.saveState(); err != nil {
		return m, func() tea.Msg { return errorFlashMsg{text: fmt.Sprintf("save failed: %v", err)} }
	}
	m.memoriesTab.setState(m.state)
	m.injectionTab.setState(m.state)
	m.historyTab.setState(m.state)
	m.settingsTab.setState(m.state)
	return m, nil
}

func (m rootModel) handleAddMemory(msg addMemoryMsg) (tea.Model, tea.Cmd) {
	if m.state == nil || m.state.Store == nil || m.isRefreshing {
		return m, nil
	}
	updated, _, err := memoryloop.AddManualRecord(m.state.Store.Records, msg.input, time.Now())
	if err != nil {
		return m, func() tea.Msg { return errorFlashMsg{text: err.Error()} }
	}
	m.state.Store.Records = updated
	if err := m.saveState(); err != nil {
		return m, func() tea.Msg { return errorFlashMsg{text: fmt.Sprintf("save failed: %v", err)} }
	}
	m.memoriesTab.setState(m.state)
	m.injectionTab.setState(m.state)
	m.historyTab.setState(m.state)
	m.settingsTab.setState(m.state)
	return m, nil
}

func (m rootModel) handlePrune() (tea.Model, tea.Cmd) {
	if m.state == nil || m.state.Store == nil || m.isRefreshing {
		return m, nil
	}
	updated, result := memoryloop.PruneRecords(m.state.Store.Records, time.Now())
	m.state.Store.Records = updated
	if err := m.saveState(); err != nil {
		return m, func() tea.Msg { return errorFlashMsg{text: fmt.Sprintf("save failed: %v", err)} }
	}
	m.memoriesTab.setState(m.state)
	m.injectionTab.setState(m.state)
	m.historyTab.setState(m.state)
	m.settingsTab.setState(m.state)
	msg := fmt.Sprintf("Pruned %d records", result.ArchivedCount)
	return m, func() tea.Msg { return errorFlashMsg{text: msg} }
}

func (m rootModel) handleSettingsChanged(msg settingsChangedMsg) (tea.Model, tea.Cmd) {
	if m.state == nil || m.state.Store == nil {
		return m, nil
	}
	if msg.mode != nil {
		m.state.Store.Mode = *msg.mode
	}
	if msg.activationPolicy != nil {
		m.state.Store.ActivationPolicy = *msg.activationPolicy
	}
	if msg.maxInjected != nil {
		m.state.Store.MaxInjected = *msg.maxInjected
	}
	if err := m.saveState(); err != nil {
		return m, func() tea.Msg { return errorFlashMsg{text: fmt.Sprintf("save failed: %v", err)} }
	}
	m.memoriesTab.setState(m.state)
	m.injectionTab.setState(m.state)
	m.historyTab.setState(m.state)
	m.settingsTab.setState(m.state)
	return m, nil
}

func (m rootModel) activeTabHints() string {
	switch m.activeTab {
	case tabMemories:
		return "j/k navigate · enter expand · f filter · a activate · s suppress · x archive · n new · ? help"
	case tabInjection:
		return "i focus input · enter test · esc unfocus · j/k navigate · ? help"
	case tabHistory:
		return "j/k navigate · R refresh · ? help"
	case tabSettings:
		return "m mode · p policy · +/- max injected · ? help"
	default:
		return "? help · q quit"
	}
}

func (m rootModel) activeTabInfo() string {
	if m.state == nil || m.state.Store == nil {
		return ""
	}
	switch m.activeTab {
	case tabMemories:
		return fmt.Sprintf("%d records", len(m.state.Store.Records))
	case tabInjection:
		return fmt.Sprintf("%d logs", len(m.state.InjectionLogs))
	case tabHistory:
		return fmt.Sprintf("%d refreshes", len(m.state.Store.RefreshHistory))
	default:
		return ""
	}
}

func (m rootModel) renderHelp() string {
	var b strings.Builder
	b.WriteString(m.styles.render(m.styles.bold, "Keyboard Shortcuts"))
	b.WriteString("\n\n")

	b.WriteString(m.styles.render(m.styles.title, "Global"))
	b.WriteString("\n")
	b.WriteString("  Tab/Shift+Tab  cycle tabs    1-4  jump to tab\n")
	b.WriteString("  q              quit          ?    toggle help\n")
	b.WriteString("\n")

	b.WriteString(m.styles.render(m.styles.title, "Memories"))
	b.WriteString("\n")
	b.WriteString("  j/k  navigate    enter  toggle detail    f  filter    /  search\n")
	b.WriteString("  a    activate    P      promote          s  suppress  u  unsuppress\n")
	b.WriteString("  x    archive     D      prune            n  new memory\n")
	b.WriteString("\n")

	b.WriteString(m.styles.render(m.styles.title, "Injection"))
	b.WriteString("\n")
	b.WriteString("  i  focus input    enter  test prompt    esc  unfocus    j/k  navigate\n")
	b.WriteString("\n")

	b.WriteString(m.styles.render(m.styles.title, "History"))
	b.WriteString("\n")
	b.WriteString("  j/k  navigate    R  trigger refresh\n")
	b.WriteString("\n")

	b.WriteString(m.styles.render(m.styles.title, "Settings"))
	b.WriteString("\n")
	b.WriteString("  m  cycle mode    p  cycle policy    +/-  max injected\n")

	return b.String()
}

